tags: {
  async list() {
    return MailServices.tags
      .getAllTags()
      .map(({ key, tag, color, ordinal }) => ({
        key,
        tag,
        color: color.toUpperCase(),
        ordinal,
      }));
  },
  async get(key) {
    key = key.toLowerCase();
    const matchingTag = MailServices.tags
      .getAllTags()
      .find(t => t.key == key);
    if (!matchingTag) {
      throw new ExtensionError(`Specified tag does not exist: ${key}`);
    }
    return {
      key: matchingTag.key,
      tag: matchingTag.tag,
      color: matchingTag.color.toUpperCase(),
      ordinal: matchingTag.ordinal,
    };
  },
